#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn observability_access_round_trip() {
        let mut pkt = ObservabilityAccess::default();
        pkt.header = PacketHeader::default();
        pkt.stage = 0x02u8;
        pkt.reason = 0x0066u16;
        pkt.access_level = 0x04u8;
        pkt.access_key = [0x05u8; 32];

        let mut buf = [0u8; ObservabilityAccess::FIXED_SIZE];
        let written = pkt.serialize(&mut buf).expect("serialize failed");
        assert_eq!(written, ObservabilityAccess::FIXED_SIZE);

        let parsed = ObservabilityAccess::deserialize(&buf).expect("deserialize failed");
        assert_eq!(pkt, parsed);
    }

    #[test]
    fn runtime_observation_round_trip() {
        let mut pkt = RuntimeObservation::default();
        pkt.header = PacketHeader::default();
        pkt.stage = 0x02u8;
        pkt.target = 0x03u8;
        pkt.reason = 0x0067u16;
        pkt.observation_data = 0x05u8;

        let mut buf = vec![0u8; RuntimeObservation::FIXED_SIZE + 1024];
        let written = pkt.serialize(&mut buf).expect("serialize failed");
        let parsed = RuntimeObservation::deserialize(&buf[..written]).expect("deserialize failed");
        assert_eq!(pkt, parsed);
    }

    #[test]
    fn verify_sizes() {
        assert_eq!(ObservabilityAccess::FIXED_SIZE, 46);
        assert_eq!(RuntimeObservation::FIXED_SIZE, 18);
    }
}
